#include "ultrapool/core.hpp"
#include <cstdio>
#include <cstdlib>
#include <memory>
using namespace up;
namespace {
unsigned checks=0;
void verify(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"FAIL IDENTITY EFFECT: %s\n",why);std::exit(1);}}
void owned(Game& g,unsigned slot,BallKey key,unsigned level,int value,unsigned mix=0){g.inventory[slot]=default_item(id_of(key),level);g.inventory[slot].score=value;g.inventory[slot].mixed_with=static_cast<uint16_t>(mix);}
void start(Game& g){g.begin_round();g.target=1000000;g.world.pockets_enabled=false;}
unsigned body(Game& g,unsigned owner){for(unsigned i=1;i<g.world.count;++i)if(g.world.balls[i].owner==static_cast<int>(owner))return i;verify(false,"owned body exists");return 0;}
void arena(Game& g){g=Game();g.phase=Phase::Aiming;g.target=1000000;g.world.pockets_enabled=false;Ball cue;cue.cue=true;cue.p=Vec(0,300);g.world.add(cue);g.snacks={};g.actions={};}
unsigned add(Game& g,BallKey key,unsigned level=1,int value=1,Vec p=Vec(100,-100)){Ball b;b.def=builtin(id_of(key));b.level=static_cast<uint8_t>(level);b.def.base_score=value;b.p=p;g.world.add(b);return g.world.last_added;}
void pocket(Game& g,unsigned i){g.world.balls[i].active=false;g.world.balls[i].v=Vec();++g.world.metrics.ticks;g.world.events.push(EventKind::Pocketed,i,6,g.world.metrics.ticks,g.world.balls[i].generation);g.dispatch();}
void hit(Game& g,unsigned a,unsigned b){g.world.events.push(EventKind::Collision,a,b,g.world.metrics.ticks,g.world.balls[a].generation,g.world.balls[b].generation);g.dispatch();}
void resolve(Game& g){for(unsigned i=0;i<4000 && g.pending_actions();++i)g.update(tick_dt);verify(!g.pending_actions(),"identity/event carriers finish");}
}
unsigned identity_effect_tests(){
 auto storage=std::unique_ptr<Game>(new Game());Game& g=*storage;
 for(BallKey key:{BallKey::MIMIC,BallKey::WITCH,BallKey::CEO,BallKey::ICECUBE,BallKey::TIME_MACHINE,BallKey::RACOON})verify(ball_supported(id_of(key)),"verified content has native binding");
 g=Game();owned(g,0,BallKey::GOLDEN_BALL,2,5,id_of(BallKey::CHICKEN));owned(g,1,BallKey::MIMIC,3,12);start(g);unsigned mimic=body(g,1);verify(g.world.balls[mimic].def.id==id_of(BallKey::GOLDEN_BALL) && g.world.balls[mimic].mixed_with==id_of(BallKey::CHICKEN),"plain Mimic copies both front identities");verify(g.world.balls[mimic].level==3 && g.world.balls[mimic].def.base_score==12 && g.world.balls[mimic].owner==1,"Mimic preserves own level/value/owner");verify(g.inventory[1].id==id_of(BallKey::MIMIC) && g.inventory[1].mixed_with==0 && g.inventory[1].score==12,"Mimic does not change permanent inventory");unsigned eggs=0;for(const auto& a:g.actions)if(a.kind==ActionKind::Spawn && a.snapshot.def.id==id_of(BallKey::EGG)){verify(a.snapshot.level==2 || a.snapshot.level==3,"copied Chicken sees retained level");++eggs;}verify(eggs==2,"Mimic suppresses early Spawn and participates once in shared setup Spawn pass");
 g=Game();owned(g,0,BallKey::GOLDEN_BALL,1,2,id_of(BallKey::CHICKEN));owned(g,1,BallKey::MIMIC,2,8,id_of(BallKey::BREAD));start(g);mimic=body(g,1);verify(g.world.balls[mimic].def.id==id_of(BallKey::GOLDEN_BALL) && g.world.balls[mimic].mixed_with==id_of(BallKey::BREAD),"mixed primary Mimic preserves unrelated secondary");
 g=Game();owned(g,0,BallKey::GOLDEN_BALL,1,2,id_of(BallKey::CHICKEN));owned(g,1,BallKey::MIMIC,2,8,id_of(BallKey::GOLDEN_BALL));start(g);mimic=body(g,1);verify(g.world.balls[mimic].def.id==id_of(BallKey::GOLDEN_BALL) && g.world.balls[mimic].mixed_with==id_of(BallKey::CHICKEN),"primary replacement that collapses duplicate can inherit front secondary");
 g=Game();owned(g,0,BallKey::GOLDEN_BALL,1,2);owned(g,1,BallKey::BREAD,2,8,id_of(BallKey::MIMIC));start(g);mimic=body(g,1);verify(g.world.balls[mimic].def.id==id_of(BallKey::BREAD) && g.world.balls[mimic].mixed_with==id_of(BallKey::GOLDEN_BALL),"secondary Mimic uses front primary when front is unmixed");
 g=Game();owned(g,0,BallKey::GOLDEN_BALL,1,2,id_of(BallKey::CHICKEN));owned(g,1,BallKey::BREAD,2,8,id_of(BallKey::MIMIC));start(g);mimic=body(g,1);verify(g.world.balls[mimic].def.id==id_of(BallKey::BREAD) && g.world.balls[mimic].mixed_with==id_of(BallKey::CHICKEN),"secondary Mimic copies front secondary when mixed");
 g=Game();owned(g,0,BallKey::B_1_BALL,1,1);owned(g,1,BallKey::MIMIC,2,12);start(g);mimic=body(g,1);verify(g.world.balls[mimic].def.id==number_id(12) && g.world.balls[mimic].def.base_score==12,"Number-copy normalization uses Mimic's own nontemporary value");
 g=Game();owned(g,1,BallKey::MIMIC,2,8);start(g);verify(g.world.balls[body(g,1)].def.id==id_of(BallKey::MIMIC),"missing front build body leaves Mimic unchanged");
 for(unsigned mixed=0;mixed<2;++mixed){g=Game();g.shop_sets={ItemSet::CLASSIC,ItemSet::NONE,ItemSet::NONE};owned(g,0,BallKey::WITCH,3,2);owned(g,4,BallKey::BREAD,2,9,mixed?id_of(BallKey::GOLDEN_BALL):0);start(g);unsigned target=body(g,4);unsigned carriers=0;for(const auto& a:g.actions)if(a.kind==ActionKind::ModifierBall){verify(a.target==target && a.bonus==3 && a.flags==static_cast<unsigned>(Modifier::Reroll),"Witch targets slot five with one combined permanent reroll/buff carrier");++carriers;}verify(carriers==1,"Witch creates one carrier");resolve(g);const Ball& changed=g.world.balls[target];verify(changed.def.id!=id_of(BallKey::BREAD) && changed.def.id!=id_of(BallKey::GOLDEN_BALL),"Witch excludes old ordered identities");verify(!changed.mixed_with || (changed.mixed_with!=id_of(BallKey::BREAD) && changed.mixed_with!=id_of(BallKey::GOLDEN_BALL)),"both rerolled sides exclude original identities");verify(g.inventory[4].id==changed.def.id && g.inventory[4].mixed_with==changed.mixed_with && g.inventory[4].score==12 && changed.def.base_score==12 && changed.level==2,"Witch updates permanent identities and value while preserving level");verify(g.inventory[0].id==id_of(BallKey::WITCH) && g.inventory[0].score==2,"Witch does not reroll or buff itself instead of target slot");}
 g=Game();owned(g,0,BallKey::WITCH,3,2);owned(g,1,BallKey::BREAD,2,9);start(g);verify(!g.pending_actions(),"missing slot five does not fall back to a different front body");
 g=Game();owned(g,0,BallKey::CEO,5,2);start(g);unsigned repeats=0;for(const auto& a:g.actions)if(a.kind==ActionKind::RepeatPocket){verify(a.repeats==4 && a.multiplier==-1 && a.due==g.world.metrics.ticks+18,"CEO schedules level-count random-with-replacement penalties at 0.1 second spacing");++repeats;}verify(repeats==1,"CEO creates one series");resolve(g);float total=0;for(const auto& p:g.world.pockets)total+=p.multiplier;verify(total==7,"CEO level five removes five total pocket multipliers");
 g=Game();owned(g,0,BallKey::GOLDEN_BALL,1,2,id_of(BallKey::CEO));owned(g,1,BallKey::MIMIC,3,8);start(g);resolve(g);total=0;for(const auto& p:g.world.pockets)total+=p.multiplier;verify(total==8,"Mimic's newly inherited secondary RoundStart effect participates after primary transformation");
 g=Game();g.shop_sets={ItemSet::CLASSIC,ItemSet::NONE,ItemSet::NONE};unsigned empty_rolls=0;for(unsigned i=0;i<500;++i){unsigned result=g.roll_content(id_of(BallKey::PANTS),0,0,11);empty_rolls+=result==0;if(result)verify(result!=id_of(BallKey::PANTS) && ball_info(result).set==ItemSet::CLASSIC,"rarity roll stays in eligible set and exclusion pool");}verify(empty_rolls>0,"selecting excluded-only legendary tier returns empty instead of falling back to another rarity");
 g=Game();owned(g,0,BallKey::ICECUBE,3,2);start(g);resolve(g);unsigned shields=0;int bonuses=0;for(const auto& p:g.world.pockets){shields+=p.shielded;bonuses+=p.bonus;}verify(shields==1 && bonuses==3,"Icecube shields exactly one pocket and adds its level score");
 arena(g);unsigned machine=add(g,BallKey::TIME_MACHINE,4,2);unsigned source=add(g,BallKey::BREAD,3,17);g.world.balls[source].mixed_with=id_of(BallKey::GOLDEN_BALL);g.world.balls[source].star_power=true;g.world.balls[source].temp_value=6;pocket(g,source);unsigned copies=0;for(const auto& a:g.actions)if(a.kind==ActionKind::Spawn){verify(a.snapshot.def.id==id_of(BallKey::BREAD) && a.snapshot.mixed_with==id_of(BallKey::GOLDEN_BALL) && a.snapshot.level==1 && a.snapshot.def.base_score==4 && a.snapshot.temp_value==0 && a.snapshot.star_power,"Time Machine snapshots mixed item/status at level one and own-level raw value");++copies;}verify(copies==1,"higher-level pocket creates one Time Machine carrier");resolve(g);verify(g.world.balls[3].owner==-1 && g.world.balls[3].level==1 && g.world.balls[3].def.base_score==4,"Time Machine lands a temporary level-one copy");pocket(g,3);verify(!g.pending_actions(),"pocketing its level-one copy cannot create another Time Machine copy");verify(g.world.balls[machine].active,"observer stays on table");
 arena(g);add(g,BallKey::TIME_MACHINE,5,2);source=add(g,BallKey::BREAD,1,17);pocket(g,source);verify(!g.pending_actions(),"level-one pocket is ineligible regardless of value");
 for(unsigned level=1;level<=5;++level){arena(g);unsigned racoon=add(g,BallKey::RACOON,level,2);set_ball_weight(g.world.balls[racoon],Weight::Heavy);source=add(g,BallKey::FISH,1,7);set_ball_weight(g.world.balls[source],Weight::Light);hit(g,racoon,source);verify(!g.world.balls[source].active && g.score==7 && g.world.balls[racoon].def.base_score==2+static_cast<int>(std::ceil(7*level*.5)),"Racoon synchronously pockets lighter victim then gains ceiling-scaled value");}
 arena(g);unsigned racoon=add(g,BallKey::RACOON,3,2);source=add(g,BallKey::BREAD,1,7);hit(g,racoon,source);verify(g.world.balls[source].active && g.world.balls[racoon].def.base_score==2 && g.score==0,"equal-weight target is not eaten");set_ball_weight(g.world.balls[racoon],Weight::Heavy);hit(g,racoon,0);verify(g.world.balls[0].active && g.score==0,"Racoon excludes player ball");
 arena(g);racoon=add(g,BallKey::RACOON,3,2);set_ball_weight(g.world.balls[racoon],Weight::Heavy);source=add(g,BallKey::FISH,1,7);set_ball_weight(g.world.balls[source],Weight::Light);g.world.balls[source].shielded=true;hit(g,racoon,source);verify(g.world.balls[source].active && g.world.balls[source].shield_broken && g.score==7 && g.world.balls[racoon].def.base_score==13,"shielded victim respawns through ordinary pocket transaction before Racoon buff");
 std::printf("Identity and remaining-event checks: %u\n",checks);return checks;
}
